CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) COLLATE utf8mb4_bin NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('admin','operator') NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB;
CREATE TABLE admin_sessions (token_digest BINARY(32) PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, expires_at DATETIME(3) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id), INDEX(expires_at)) ENGINE=InnoDB;
CREATE TABLE events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, public_id VARCHAR(40) COLLATE utf8mb4_bin NOT NULL UNIQUE, workspace_id BIGINT UNSIGNED NOT NULL DEFAULT 1, state ENUM('DRAFT','PUBLISHED','PAUSED','CLOSED') NOT NULL DEFAULT 'DRAFT', config JSON NOT NULL, policy_epoch INT UNSIGNED NOT NULL DEFAULT 1, form_version INT UNSIGNED NOT NULL DEFAULT 1, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB;
CREATE TABLE event_members (event_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(event_id,user_id), FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE form_versions (event_id BIGINT UNSIGNED NOT NULL, version INT UNSIGNED NOT NULL, fields JSON NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY(event_id,version), FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE participants (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, event_id BIGINT UNSIGNED NOT NULL, identity_digest BINARY(32) NOT NULL, identity_value VARCHAR(120) NOT NULL, identity_key_version SMALLINT NOT NULL DEFAULT 1, answers JSON NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(event_id,identity_digest), FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE display_sessions (token_digest BINARY(32) PRIMARY KEY, event_id BIGINT UNSIGNED NOT NULL, expires_at DATETIME(3) NOT NULL, revoked BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE, INDEX(expires_at)) ENGINE=InnoDB;
CREATE TABLE checkin_sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, selector VARCHAR(40) COLLATE utf8mb4_bin NOT NULL UNIQUE, token_digest BINARY(32) NOT NULL UNIQUE, event_id BIGINT UNSIGNED NOT NULL, browser_digest BINARY(32) NOT NULL, form_version INT UNSIGNED NOT NULL, policy_epoch INT UNSIGNED NOT NULL, expires_at DATETIME(3) NOT NULL, consumed BOOLEAN NOT NULL DEFAULT FALSE, result_id BIGINT UNSIGNED NULL, FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE, INDEX(expires_at)) ENGINE=InnoDB;
CREATE TABLE checkins (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, event_id BIGINT UNSIGNED NOT NULL, identity_digest BINARY(32) NOT NULL, participant_id BIGINT UNSIGNED NULL, identity_value VARCHAR(120) NOT NULL, answers JSON NOT NULL, status ENUM('CHECKED_IN','PENDING_REVIEW','REVOKED') NOT NULL, source ENUM('online','manual') NOT NULL, checked_in_at DATETIME(3) NOT NULL, receipt_id VARCHAR(50) COLLATE utf8mb4_bin NOT NULL UNIQUE, form_version INT UNSIGNED NOT NULL, policy_epoch INT UNSIGNED NOT NULL, UNIQUE(event_id,identity_digest), INDEX(event_id,status,checked_in_at,id), INDEX(event_id,checked_in_at,id), FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE checkin_evidence (checkin_id BIGINT UNSIGNED PRIMARY KEY, encrypted_data TEXT NOT NULL, browser_digest BINARY(32) NULL, risk_flags JSON NOT NULL, location_result VARCHAR(60) NOT NULL, expires_at DATETIME(3) NOT NULL, FOREIGN KEY(checkin_id) REFERENCES checkins(id) ON DELETE CASCADE, INDEX(expires_at)) ENGINE=InnoDB;
CREATE TABLE idempotency_records (session_id BIGINT UNSIGNED NOT NULL, key_digest BINARY(32) NOT NULL, request_digest BINARY(32) NOT NULL, result_id BIGINT UNSIGNED NOT NULL, expires_at DATETIME(3) NOT NULL, PRIMARY KEY(session_id,key_digest), FOREIGN KEY(session_id) REFERENCES checkin_sessions(id) ON DELETE CASCADE, FOREIGN KEY(result_id) REFERENCES checkins(id) ON DELETE CASCADE, INDEX(expires_at)) ENGINE=InnoDB;
CREATE TABLE import_jobs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, event_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, data JSON NOT NULL, committed BOOLEAN NOT NULL DEFAULT FALSE, expires_at DATETIME(3) NOT NULL, FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE, INDEX(expires_at)) ENGINE=InnoDB;
CREATE TABLE attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, event_id BIGINT UNSIGNED NULL, reason_code VARCHAR(80) NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX(created_at)) ENGINE=InnoDB;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, event_id BIGINT UNSIGNED NULL, action VARCHAR(80) NOT NULL, reason VARCHAR(500) NOT NULL DEFAULT '', created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX(event_id,created_at), INDEX(created_at)) ENGINE=InnoDB;
CREATE TABLE deletion_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, event_public_id VARCHAR(40) COLLATE utf8mb4_bin NOT NULL, deleted_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB;
